mapper.select:
SELECT 
FROM care_plan cp
LEFT JOIN elder e ON cp.elder_id = e.id


        AND cp.plan_name LIKE CONCAT('%', #{planName}, '%')


        AND e.name LIKE CONCAT('%', #{elderName}, '%')


        AND cp.care_level = #{careLevel}


        AND cp.status = #{status}


        AND cp.elder_id = #{elderId}


ORDER BY cp.create_time DESC

mapper.update:
UPDATE care_plan
plan_name = #{planName}, care_level = #{careLevel}, start_date = #{startDate}, end_date = #{endDate}, status = #{status}, nurse_id = #{nurseId}, nurse_name = #{nurseName}, diet_plan = #{dietPlan}, medication_plan = #{medicationPlan}, daily_care = #{dailyCare}, rehabilitation_plan = #{rehabilitationPlan}, special_notes = #{specialNotes}
WHERE id = #{id}
